package com.videomind.module.auth;
import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;import com.videomind.common.exception.BizException;import com.videomind.module.auth.entity.*;import com.videomind.module.auth.mapper.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.time.*;import java.util.*;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class AuthService{private final AppUserMapper users;private final UserRefreshTokenMapper tokens;private final PasswordEncoder encoder;private final JwtService jwt;private final AuthProperties p;public AuthService(AppUserMapper u,UserRefreshTokenMapper t,PasswordEncoder e,JwtService j,AuthProperties p){users=u;tokens=t;encoder=e;jwt=j;this.p=p;}@Transactional public TokenPair register(String name,String password){String n=normalize(name);if(find(n)!=null)throw new BizException(409,"用户名已存在");AppUser u=new AppUser();u.setPublicId(UUID.randomUUID().toString());u.setUsername(n);u.setPasswordHash(encoder.encode(password));u.setEnabled(true);u.setCreatedAt(LocalDateTime.now());users.insert(u);return issue(u);}public TokenPair login(String name,String password){AppUser u=find(normalize(name));if(u==null||!Boolean.TRUE.equals(u.getEnabled())||!encoder.matches(password,u.getPasswordHash()))throw new BizException(401,"用户名或密码错误");return issue(u);}@Transactional public TokenPair refresh(String raw){UserRefreshToken t=tokens.selectOne(new LambdaQueryWrapper<UserRefreshToken>().eq(UserRefreshToken::getTokenHash,hash(raw)).isNull(UserRefreshToken::getRevokedAt));if(t==null||t.getExpiresAt().isBefore(LocalDateTime.now()))throw new BizException(401,"刷新令牌无效或已过期");t.setRevokedAt(LocalDateTime.now());tokens.updateById(t);AppUser u=users.selectById(t.getUserId());return issue(u);}@Transactional public void revoke(String raw){if(raw==null)return;UserRefreshToken t=tokens.selectOne(new LambdaQueryWrapper<UserRefreshToken>().eq(UserRefreshToken::getTokenHash,hash(raw)));if(t!=null){t.setRevokedAt(LocalDateTime.now());tokens.updateById(t);}}public AppUser user(Long id){return users.selectById(id);}private TokenPair issue(AppUser u){String raw=random();UserRefreshToken t=new UserRefreshToken();t.setUserId(u.getId());t.setTokenHash(hash(raw));t.setCreatedAt(LocalDateTime.now());t.setExpiresAt(LocalDateTime.now().plusDays(p.getRefreshDays()));tokens.insert(t);return new TokenPair(jwt.issue(u.getId(),u.getUsername()),raw,jwt.expiresIn(),u.getPublicId(),u.getUsername());}private AppUser find(String n){return users.selectOne(new LambdaQueryWrapper<AppUser>().eq(AppUser::getUsername,n));}private String normalize(String n){String s=n==null?"":n.trim().toLowerCase();if(!s.matches("[a-z0-9_\\-]{3,32}"))throw new BizException(400,"用户名格式不正确");return s;}private String random(){byte[]b=new byte[48];new SecureRandom().nextBytes(b);return Base64.getUrlEncoder().withoutPadding().encodeToString(b);}private String hash(String v){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(String.valueOf(v).getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}public record TokenPair(String accessToken,String refreshToken,long expiresIn,String subject,String username){} }
